<script setup lang="ts">
import {ref} from 'vue'
import AppModal from './AppModal.vue'
import {request} from '@/services/quality'
interface Report{id:number;revision:number;version:number;status:string;actual_starts_at:string;actual_ends_at:string;attendance:string;activities:string;decisions:string;next_steps:string}
interface Visit{id:number;title:string;mode:string;place:string;starts_at:string;ends_at:string;status:string;version:number;previous_id:number|null;decision_reason:string|null;reports:Report[]}
const props=defineProps<{missionId:number;active:boolean}>();const emit=defineEmits<{changed:[]}>()
const open=ref(false),editor=ref(false),busy=ref(false),error=ref(''),dialogError=ref(''),notice=ref(''),lead=ref(false),admin=ref(false),agreed=ref(false),rows=ref<Visit[]>([]),selected=ref<Visit|null>(null),selectedReport=ref<Report|null>(null),reading=ref<Report|null>(null),kind=ref('create'),action=ref('propose')
const requestKey=ref('')
const form=ref({title:'',mode:'onsite',place:'',starts:'',ends:'',reason:'',attendance:'',activities:'',decisions:'',next_steps:''})
const labels:Record<string,string>={draft:'Brouillon',proposed:'Proposée',confirmed:'Confirmée',completed:'Réalisée',rescheduled:'Reportée',cancelled:'Annulée',submitted:'Soumis',shared:'Partagé'}
const actions:Record<string,string>={propose:'Proposer l’intervention',confirm:'Confirmer l’intervention',cancel:'Annuler l’intervention',reschedule:'Reporter l’intervention',complete:'Marquer réalisée',submit:'Soumettre le compte rendu',share:'Partager le compte rendu'}
const local=(value:string)=>new Date(value).toLocaleString('sv-SE',{timeZone:'Africa/Porto-Novo'}).replace(' ','T').slice(0,16)
const date=(value:string)=>new Date(value).toLocaleString('fr-FR',{timeZone:'Africa/Porto-Novo'})
const iso=(value:string)=>value+':00+01:00'
async function load(){busy.value=true;error.value='';try{const d=await request<{data:Visit[];can_lead:boolean;can_admin:boolean}>(`/support/missions/${props.missionId}/visits`);rows.value=d.data;lead.value=d.can_lead;admin.value=d.can_admin}catch(e){rows.value=[];lead.value=false;admin.value=false;error.value=(e as Error).message}finally{busy.value=false}}
function prepare(type:string,v?:Visit,a='propose',report?:Report){requestKey.value=crypto.randomUUID();kind.value=type;selected.value=v||null;selectedReport.value=report||null;action.value=a;agreed.value=false;dialogError.value='';const start=report?.actual_starts_at||v?.starts_at||new Date(Date.now()+86400000).toISOString();const end=report?.actual_ends_at||v?.ends_at||new Date(Date.now()+90000000).toISOString();form.value={title:v?.title||'',mode:v?.mode||'onsite',place:v?.place||'',starts:local(start),ends:local(end),reason:'',attendance:report?.attendance||'',activities:report?.activities||'',decisions:report?.decisions||'',next_steps:report?.next_steps||''};editor.value=true}
async function save(){busy.value=true;dialogError.value='';let path=`/support/missions/${props.missionId}/visits`,method='POST';let body:Record<string,unknown>={confirmed:agreed.value,...(kind.value==='create'?{request_key:requestKey.value}:{})};try{
 if(kind.value==='create'||action.value==='reschedule'&&kind.value==='transition'){body={...body,title:form.value.title,mode:form.value.mode,place:form.value.place,starts_at:iso(form.value.starts),ends_at:iso(form.value.ends)}}
 if(kind.value==='transition'){path+=`/${selected.value!.id}/transition`;body={...body,action:action.value,version:selected.value!.version,reason:form.value.reason}}
 if(kind.value==='report'){path+=`/${selected.value!.id}/reports`;if(selectedReport.value){path+='/'+selectedReport.value.id;method='PATCH'}body={...body,visit_version:selected.value!.version,...(selectedReport.value?{version:selectedReport.value.version}:{}),actual_starts_at:iso(form.value.starts),actual_ends_at:iso(form.value.ends),attendance:form.value.attendance,activities:form.value.activities,decisions:form.value.decisions,next_steps:form.value.next_steps}}
 if(kind.value==='reportDecision'){path+=`/${selected.value!.id}/reports/${selectedReport.value!.id}/decision`;body={...body,action:action.value,version:selectedReport.value!.version}}
 await request(path,method,body);notice.value='Enregistrement effectué. Consultez l’état de publication ; un brouillon n’est pas partagé.';await load();editor.value=false;emit('changed')
 }catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><button class="button secondary" @click="open=true;load()">Planning & comptes rendus</button><AppModal v-model="open" title="Interventions de la mission" :busy="busy" size="wide"><div class="form-body"><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><p>Horaires affichés en Africa/Porto-Novo (UTC+1). Un report conserve l’ancienne occurrence ; une nouvelle confirmation de l’officine est nécessaire.</p><button v-if="lead&&active" class="button primary" @click="prepare('create')">Planifier une intervention</button><article v-for="v in rows" :key="v.id" class="detail-card" style="margin-top:16px"><h3>{{v.title}}</h3><p>{{date(v.starts_at)}} → {{date(v.ends_at)}} · {{labels[v.status]}} · v{{v.version}}</p><p>{{v.mode==='onsite'?'Présentiel':'À distance'}} · {{v.place}}</p><p v-if="v.previous_id">Nouvelle occurrence issue de l’intervention #{{v.previous_id}}</p><p v-if="v.decision_reason">Dernière décision : {{v.decision_reason}}</p><div class="heading-actions" style="flex-wrap:wrap"><button v-if="lead&&active&&v.status==='draft'" class="button primary small" @click="prepare('transition',v,'propose')">Proposer</button><button v-if="admin&&active&&v.status==='proposed'" class="button primary small" @click="prepare('transition',v,'confirm')">Confirmer la visite</button><button v-if="lead&&active&&['proposed','confirmed'].includes(v.status)" class="button secondary small" @click="prepare('transition',v,'reschedule')">Reporter</button><button v-if="(lead||admin)&&['draft','proposed','confirmed'].includes(v.status)" class="button secondary small" @click="prepare('transition',v,'cancel')">Annuler la visite</button><button v-if="lead&&active&&['confirmed','completed'].includes(v.status)&&!v.reports.some(r=>r.status!=='shared')" class="button secondary small" @click="prepare('report',v)">Rédiger une révision du compte rendu</button><button v-if="lead&&active&&v.status==='confirmed'&&v.reports.some(r=>r.status==='shared')" class="button secondary small" @click="prepare('transition',v,'complete')">Marquer réalisée</button></div><h4>Comptes rendus</h4><p v-if="!v.reports.length">Aucun compte rendu visible dans votre périmètre.</p><div v-for="r in v.reports" :key="r.id" class="detail-card"><p>Révision {{r.revision}} · {{labels[r.status]}} · v{{r.version}}</p><div class="heading-actions" style="flex-wrap:wrap"><button class="button secondary small" @click="reading=r">Voir le compte rendu</button><template v-if="lead&&active"><button v-if="r.status==='draft'" class="button secondary small" @click="prepare('report',v,'propose',r)">Modifier le brouillon</button><button v-if="r.status==='draft'" class="button primary small" @click="prepare('reportDecision',v,'submit',r)">Soumettre</button><button v-if="r.status==='submitted'" class="button primary small" @click="prepare('reportDecision',v,'share',r)">Partager</button></template></div></div></article><p v-if="!rows.length&&!error">Aucune intervention visible.</p></div><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Fermer</button></template></AppModal>
<AppModal v-model="editor" :title="kind==='create'?'Planifier une intervention':kind==='report'?'Brouillon de compte rendu':actions[action]" :busy="busy" size="wide"><form id="mission-visit-operation" class="form-body form-grid" @submit.prevent="save"><p v-if="dialogError" class="alert error span-2" role="alert">{{dialogError}}</p><template v-if="kind==='create'||kind==='transition'&&action==='reschedule'"><label>Objet de l’intervention<input v-model="form.title" required maxlength="180"/></label><label>Mode<select v-model="form.mode"><option value="onsite">Présentiel</option><option value="remote">À distance</option></select></label><label class="span-2">Lieu ou lien privé<input v-model="form.place" required maxlength="500"/></label></template><template v-if="kind==='create'||kind==='report'||kind==='transition'&&action==='reschedule'"><label>{{kind==='report'?'Début réel':'Début prévu'}} · UTC+1<input v-model="form.starts" required type="datetime-local"/></label><label>{{kind==='report'?'Fin réelle':'Fin prévue'}} · UTC+1<input v-model="form.ends" required type="datetime-local"/></label></template><template v-if="kind==='report'"><p class="module-disclaimer span-2">Renseignez les horaires réels passés. Ces sections seront partagées après soumission puis publication ; ne saisissez aucune note interne.</p><label class="span-2">Présences et absences<textarea v-model="form.attendance" required maxlength="3000"/></label><label class="span-2">Activités réalisées<textarea v-model="form.activities" required maxlength="8000" rows="5"/></label><label class="span-2">Décisions<textarea v-model="form.decisions" required maxlength="5000"/></label><label class="span-2">Prochaines étapes<textarea v-model="form.next_steps" required maxlength="3000"/></label></template><label v-if="kind==='transition'" class="span-2">Motif obligatoire<textarea v-model="form.reason" required maxlength="2000"/></label><p v-if="kind==='reportDecision'" class="span-2">{{action==='share'?'Cette version sera visible par l’officine. Vérifiez les destinataires et le contenu avant publication.':'La soumission fige cette version. Elle ne la partage pas encore avec l’officine.'}}</p><label class="checkbox-label span-2"><input v-model="agreed" type="checkbox" required/>Je confirme cette opération.</label></form><template #footer><button class="button secondary" :disabled="busy" @click="editor=false">Annuler</button><button class="button primary" :disabled="busy" form="mission-visit-operation" type="submit">Confirmer</button></template></AppModal>
<AppModal :model-value="!!reading" title="Compte rendu versionné" size="wide" @update:model-value="reading=null"><dl v-if="reading" class="form-body application-summary"><dt>Révision</dt><dd>{{reading.revision}} · {{labels[reading.status]}}</dd><dt>Réalisation déclarée</dt><dd>{{date(reading.actual_starts_at)}} → {{date(reading.actual_ends_at)}}</dd><dt>Présences / absences</dt><dd style="white-space:pre-wrap">{{reading.attendance}}</dd><dt>Activités</dt><dd style="white-space:pre-wrap">{{reading.activities}}</dd><dt>Décisions</dt><dd style="white-space:pre-wrap">{{reading.decisions}}</dd><dt>Prochaines étapes</dt><dd style="white-space:pre-wrap">{{reading.next_steps}}</dd></dl><template #footer><button class="button secondary" @click="reading=null">Fermer</button></template></AppModal></template>
